args.sparql:
SELECT ?director ?directorLabel WHERE {
  <http://dbpedia.org/resource/Robert_Rylands%27_Last_Journey> dbo:director ?director .
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER (lang(?directorLabel) = 'en') }
}

SELECT ?p ?director ?label WHERE {
  VALUES ?p { dbo:director dbp:director }
  <http://dbpedia.org/resource/Robert_Rylands%27_Last_Journey> ?p ?director .
  OPTIONAL { ?director rdfs:label ?label FILTER (lang(?label) = 'en') }
}

SELECT ?p ?o WHERE {
  ?film rdfs:label "Robert Rylands' Last Journey"@en .
  ?film ?p ?o .
} LIMIT 200

SELECT ?p ?o WHERE {
  VALUES ?p { dbp:father dbo:father dbp:parents dbo:parent dbp:parent dbp:parents_name dbp:parent_name }
  dbr:Gracia_Querejeta ?p ?o .
}

SELECT DISTINCT ?father ?fatherLabel WHERE {
  ?film rdfs:label "Robert Rylands' Last Journey"@en .
  ?film dbo:director ?director .
  VALUES ?fatherProp { dbp:father dbo:father dbp:parents dbo:parent }
  ?director ?fatherProp ?father .
  OPTIONAL { ?father rdfs:label ?fatherLabel FILTER (lang(?fatherLabel) = 'en') }
} LIMIT 50

SELECT DISTINCT ?father ?fatherLabel WHERE {
  ?film rdfs:label "Robert Rylands' Last Journey"@en .
  ?film dbo:director ?director .
  VALUES ?fatherProp { dbp:father dbo:father dbp:parents dbo:parent }
  ?director ?fatherProp ?father .
  OPTIONAL { ?father rdfs:label ?fatherLabel FILTER (lang(?fatherLabel) = 'en') }
} LIMIT 50

output.sparql:
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbo: <http://dbpedia.org/ontology/>
SELECT DISTINCT ?father ?fatherLabel WHERE {
  ?film rdfs:label "Robert Rylands' Last Journey" @en .
  ?film dbo:director ?director .
  VALUES ?fatherProp {
    dbp:father dbo:father dbp:parents dbo:parent
  }
  ?director ?fatherProp ?father .
  OPTIONAL {
    ?father rdfs:label ?fatherLabel
    FILTER(lang(?fatherLabel) = 'en')
  }
}
LIMIT 50

